WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_mm_reverse'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '多人多次反求', 'kp-trv-mm-reverse', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "多人多次反求"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "极复杂的逆向工程。已知第三次相遇在距离中点 50 米处，倒推全长。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这种题专门恶心人，给出多次相遇后的某个特定位置，反推整条路的长度。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题（画图+切片法）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这种题如果没有在草稿纸上画出两人折返的轨迹，神仙也算不出来。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[画一条长长的横线代表全长 S] --> B[标出中点位置]\nB --> C[画出甲的轨迹(实线)和乙的轨迹(虚线), 直到第三次相遇]\nC --> D[根据 (2N-1) 原理, 算出此时两人共走了 5 个 S]\nD --> E[用速度比得出某一个人单独走的距离是几个 S]\nE --> F[在图上比对这个距离和中点的关系, 找到那 50 米对应的分数 S]\nF --> G[反解出 S 的绝对长度]"}}]}$$ AS jsonb), NULL, '多人多次反求的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "多人多次反求"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_mm_reverse", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
